    private void RefreshPreview(){if(preview!=null && CurrentNote() is{} note)try{preview.Document=MarkdownDocument.Render(note.Content,VM.State!.Preferences.FontSize);}catch(Exception error){preview.Document=new FlowDocument(new Paragraph(new Run("预览暂时无法显示："+error.Message)));}}
    private void UpdateEditorStatus(){if(editorStatus!=null && textEditor!=null)editorStatus.Text=$"{Regex.Replace(textEditor.Text,@"\s","").Length:N0} 字  ·  {textEditor.LineCount} 行  ·  Ln {textEditor.TextArea.Caret.Line}, Col {textEditor.TextArea.Caret.Column}";}
    private void SetEditorView(string mode,bool save=true){if(writingGrid==null)return;writingGrid.ColumnDefinitions[0].Width=mode=="preview"?new GridLength(0):new GridLength(1,GridUnitType.Star);writingGrid.ColumnDefinitions[1].Width=new GridLength(mode=="split"?4:0);writingGrid.ColumnDefinitions[2].Width=mode=="edit"?new GridLength(0):new GridLength(1,GridUnitType.Star);if(save)VM.Change(v=>v with{Preferences=v.Preferences with{EditorView=mode}},"edit");}
    private void Wrap(string before,string after,string sample){if(textEditor==null)return;var selected=textEditor.SelectedText;var start=textEditor.SelectionStart;textEditor.Document.Replace(start,textEditor.SelectionLength,before+(selected.Length>0?selected:sample)+after);textEditor.Select(start+before.Length,(selected.Length>0?selected:sample).Length);textEditor.Focus();}
